import { Mesh, Group, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, DoubleSide, AmbientLight, DirectionalLight } from 'three/webgpu';
import { uv, mix, color, smoothstep, float, vec3, Fn, vec2, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Color } = THREE;

  const group = new Group();
  group.userData.handlers = {};

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  // --- Engineered gradient backdrop (z = -2.5) ---
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshStandardNodeMaterial({ side: DoubleSide, roughness: 0.9, metalness: 0.0 });

  const surfCol = color(colors.surface);
  const inkCol = color(colors.ink);
  const accentCol = color(colors.accent);

  // vertical engineered gradient with subtle accent seam near mid line
  const v = smoothstep(float(0.0), float(1.0), uv().y);
  let baseCol = mix(inkCol, surfCol, v);
  // hairline accent seam
  const seam = smoothstep(float(0.47), float(0.5), uv().y).sub(smoothstep(float(0.5), float(0.53), uv().y));
  baseCol = mix(baseCol, accentCol, seam.mul(float(0.18)));

  // subtle grain
  const grain = Fn(() => {
    const p = uv().mul(vec2(180, 110));
    const n = fract(sin(dot(p, vec2(12.9898, 78.233))).mul(float(43758.5453)));
    return n;
  })();

  bgMat.colorNode = baseCol.add(grain.sub(float(0.5)).mul(float(0.04)));

  const bg = new Mesh(bgGeo, bgMat);
  bg.position.set(0, 0, -2.5);
  group.add(bg);

  // --- Sprite plane with floating-accent texture, atlas region 0,0,512,320 ---
  const atlasW = 512, atlasH = 320;
  const aspect = atlasW / atlasH;
  const planeW = 2.2;
  const planeH = planeW / aspect;

  const spriteGeo = new PlaneGeometry(planeW, planeH);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide, depthWrite: false });
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    // atlas region is full texture (0,0,512,320 assumes 512x320 atlas)
    spriteMat.map = tex;
    spriteMat.needsUpdate = true;
  });

  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.position.set(0, 0.15, 0.15);
  group.add(sprite);

  // --- Title text "Journal" (Lora serif headline) ---
  const textItems = config.textContent ?? spec.textContent ?? [];
  const titleStr = (textItems.find((t) => t.role === 'headline') || textItems[0] || { text: 'Journal' }).text;
  const title = ctx.fontAtlas.createText(titleStr, {
    fontSize: 96,
    color: colors.paper,
    align: 'center',
    maxWidthPx: 720,
    letterSpacingPx: 0,
  });
  title.position.set(0, -0.05, 0.45);
  group.add(title);

  // small accent kin-dot beneath title (<=10% frame)
  const dotGeo = new PlaneGeometry(0.08, 0.08);
  const dotMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.4,
    roughness: 0.4,
    metalness: 0.0,
  });
  const dot = new Mesh(dotGeo, dotMat);
  dot.position.set(0, -0.42, 0.4);
  group.add(dot);

  // --- Lighting (node-local rim/light per doctrine) ---
  const amb = new AmbientLight(0xffffff, 0.6);
  group.add(amb);

  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(2.0, 2.4, 3.0);
  group.add(key);

  const rim = new DirectionalLight(colors.accent, 0.7);
  rim.position.set(-3.0, -0.5, -1.0);
  group.add(rim);

  // --- Entrance motion: rise-in (y +0.4 -> 0), fade-up for backdrop accent ---
  const targetY = 3;
  group.position.y = targetY + 0.4;
  group.scale.setScalar(0.985);

  const tl = gsap.timeline();
  tl.to(group.position, { y: targetY, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  // weighted-settle overshoot
  tl.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.28, ease: 'power2.out' }, 0.7);
  tl.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.5, ease: 'power3.inOut' }, 1.0);

  // accent dot idle breathing (single slow transform)
  const breath = gsap.to(dot.scale, { x: 1.18, y: 1.18, duration: 1.6, ease: 'sine.inOut', yoyo: true, repeat: -1 });

  // --- Cleanup ---
  const disposables = [
    bgGeo, bgMat, spriteGeo, spriteMat, dotGeo, dotMat,
  ];
  group.userData.cleanup = () => {
    tl.kill();
    breath.kill();
    for (const d of disposables) {
      try { d.dispose(); } catch (e) { /* noop */ }
    }
    if (spriteMat.map) spriteMat.map.dispose?.();
  };

  return group;
}
